#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int n;
    int *head;
    int *to;
    int *next;
    int edge_count;
} Tree;

void add_edge(Tree *tree, int a, int b) {
    tree->to[tree->edge_count] = b;
    tree->next[tree->edge_count] = tree->head[a];
    tree->head[a] = tree->edge_count++;

    tree->to[tree->edge_count] = a;
    tree->next[tree->edge_count] = tree->head[b];
    tree->head[b] = tree->edge_count++;
}

int bfs(Tree *tree, int start, int *dist, int *parent, int *queue) {
    for (int i = 0; i < tree->n; i++) {
        dist[i] = -1;
    }

    int front = 0, back = 0;
    queue[back++] = start;
    dist[start] = 0;
    if (parent != NULL) parent[start] = -1;

    int farthest = start;
    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[farthest]) farthest = u;

        for (int e = tree->head[u]; e != -1; e = tree->next[e]) {
            int v = tree->to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (parent != NULL) parent[v] = u;
                queue[back++] = v;
            }
        }
    }
    return farthest;
}

int find_center(Tree *tree) {
    int *dist = malloc((size_t)tree->n * sizeof(int));
    int *parent = malloc((size_t)tree->n * sizeof(int));
    int *queue = malloc((size_t)tree->n * sizeof(int));

    int endpoint = bfs(tree, 0, dist, NULL, queue);
    int other = bfs(tree, endpoint, dist, parent, queue);

    int steps = dist[other] / 2;
    int center = other;
    while (steps--) center = parent[center];

    free(dist);
    free(parent);
    free(queue);
    return center;
}

void init_tree(Tree *tree, int n) {
    tree->n = n;
    tree->edge_count = 0;
    tree->head = malloc((size_t)n * sizeof(int));
    tree->to = malloc((size_t)(2 * (n - 1)) * sizeof(int));
    tree->next = malloc((size_t)(2 * (n - 1)) * sizeof(int));

    for (int i = 0; i < n; i++) tree->head[i] = -1;
}

